INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein logisches Datenmodell immer physische Details enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf logische Struktur"}, {"text": "Ja", "correct": false, "because": "Physische Details separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein logisches Modell für eine Datenbank erstelle?', 3, '[{"text": "Entitätenbeziehungen", "correct": true, "because": "Definiert Datenstruktur"}, {"text": "Speichergröße", "correct": false, "because": "Physischer Aspekt"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem konzeptionellen Schema?', 5, '[{"text": "Entitäten", "correct": true, "because": "Repräsentieren Objekte"}, {"text": "Beziehungen", "correct": true, "because": "Verknüpfen Entitäten"}, {"text": "Hardwarezuweisung", "correct": false, "because": "Physischer Aspekt"}, {"text": "Datenkompression", "correct": false, "because": "Technische Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein konzeptionelles Schema ist datenbankunabhängig. b) Es enthält Tabellenindizes.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Indizes sind physisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein konzeptionelles Modell für ein IT-System entwerfe?', 4, '[{"text": "Kardinalitäten", "correct": false, "because": "Definieren Beziehungen"}, {"text": "Geschäftsregeln", "correct": false, "because": "Strukturieren Daten"}, {"text": "Speicherformat", "correct": true, "because": "Physischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein konzeptionelles Schema SQL-Befehle enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Abstrakt, nicht technisch"}, {"text": "Ja", "correct": false, "because": "SQL ist Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem konzeptionellen Schema?', 3, '[{"text": "Datenstruktur verstehen", "correct": true, "because": "Bietet logischen Überblick"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Technische Umsetzung"}, {"text": "Hardwareplanung", "correct": false, "because": "Nicht physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einem logischen Modell entscheidend?', 5, '[{"text": "Entitäten", "correct": true, "because": "Grundbausteine"}, {"text": "Attribute", "correct": true, "because": "Beschreiben Entitäten"}, {"text": "Datenbanktyp", "correct": false, "because": "Technische Entscheidung"}, {"text": "Speichergröße", "correct": false, "because": "Physischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein konzeptionelles Schema nutzt ER-Diagramme. b) Es definiert Speicherorte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherorte sind physisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein konzeptionelles Schema?', 4, '[{"text": "Beziehungsdefinition", "correct": false, "because": "Kern des Modells"}, {"text": "Entitätenliste", "correct": false, "because": "Grundlage des Schemas"}, {"text": "Datenbanksoftware", "correct": true, "because": "Technische Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein konzeptionelles Schema für kleine Projekte überflüssig?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit auch bei kleinen Projekten"}, {"text": "Ja", "correct": false, "because": "Nützlich unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein konzeptionelles Schema?', 4, '[{"text": "Klarheit der Datenstruktur", "correct": true, "because": "Fördert Verständnis"}, {"text": "Basis für Umsetzung", "correct": true, "because": "Leitet physisches Modell"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Technischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein logisches Modell immer technische Details enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abstrakt, keine Technik"}, {"text": "Ja", "correct": false, "because": "Fokus auf Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein konzeptionelles Schema für ein CRM-System zu erstellen?', 3, '[{"text": "ER-Diagramm", "correct": true, "because": "Visualisiert Beziehungen"}, {"text": "SQL-Skripte", "correct": false, "because": "Technische Umsetzung"}, {"text": "Hardwareplan", "correct": false, "because": "Physischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein konzeptionelles Schema zeigt Beziehungen. b) Es enthält physische Speicherorte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherorte sind physisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem logischen Modell?', 5, '[{"text": "Entitäten", "correct": true, "because": "Grundbausteine"}, {"text": "Kardinalitäten", "correct": true, "because": "Definieren Beziehungen"}, {"text": "Datenbankgröße", "correct": false, "because": "Physischer Aspekt"}, {"text": "Serverstandort", "correct": false, "because": "Technische Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein konzeptionelles Schema entwerfe?', 3, '[{"text": "Attributdefinition", "correct": false, "because": "Beschreibt Entitäten"}, {"text": "Beziehungsarten", "correct": false, "because": "Strukturiert Daten"}, {"text": "Dateiformat", "correct": true, "because": "Physischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein konzeptionelles Schema die Hardware berücksichtigen?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf logische Ebene"}, {"text": "Ja", "correct": false, "because": "Hardware ist physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein konzeptionelles Schema für die Kommunikation mit Kunden nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Klarheit für Anforderungen"}, {"text": "Nein", "correct": false, "because": "Fördert Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein konzeptionelles Schema?', 4, '[{"text": "Logische Konsistenz", "correct": true, "because": "Sichert Datenintegrität"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Sekundär"}, {"text": "Physische Details", "correct": false, "because": "Nicht enthalten"}]');
